                        "required": false,
                        "in": "header"
                    },
                    {
                        "name": "lang",
                        "schema": {
                            "type": "string",
                            "enum": [
                                "et",
                                "en",
                                "all"
                            ],
                            "example": "en",
                            "default": "all"
                        },
                        "description": "Language code",
                        "required": false,
                        "in": "query"
                    },
                    {
                        "name": "valid_on",
                        "schema": {
                            "type": "string",
                            "format": "date",
                            "example": "2025-01-01"
                        },
                        "description": "Date in ISO 8601 format (YYYY-MM-DD)",
                        "required": false,
                        "in": "query"
                    }
                ],
                "responses": {
                    "200": {
                        "content": {
                            "application/json": {
                                "schema": {
                                    "type": "array",
                                    "items": {
                                        "type": "object",
                                        "properties": {
                                            "id": {
                                                "type": "string",
                                                "description": "Unique identifier",
                                                "example": "UNSPECIFIED_HOUSEHOLD"
                                            },
                                            "sort": {
                                                "type": "integer",
                                                "description": "Sorting order",
                                                "example": 10
                                            },
                                            "valid_from": {
                                                "type": "string",
                                                "description": "Date from which the item is valid",
                                                "example": "2024-01-01"
                                            },
                                            "valid_to": {
                                                "type": "string",
                                                "nullable": true,
                                                "description": "Date until which the item is valid, can be null if indefinite",
                                                "example": null
                                            },
                                            "name": {
                                                "oneOf": [
                                                    {
                                                        "type": "object",
                                                        "additionalProperties": {
                                                            "type": "string",
                                                            "description": "Name in different languages (if paramtere lang=all (default))"
                                                        },
                                                        "description": "Name as a dictionary with language codes as keys (if lang=all (default))",
                                                        "example": {
                                                            "en": "Unspecified households (in English)",
                                                            "et": "Unspecified households (in Estonian)"
                                                        }
                                                    },
                                                    {
                                                        "type": "string",
                                                        "description": "Name as a simple string (if lang=et or lang=en)",
                                                        "example": "Unspecified households"
                                                    }
                                                ]
                                            }
                                        }
                                    }
                                }
                            }
                        },
                        "description": "Successful operation"
                    }
                }
            }
        },
